import json, pathlib, sys
sys.path.insert(0,str(pathlib.Path(__file__).parent));import sentinel as s
R=s.ROOT/'contracts'
def dump(n,o): (R/n).write_text(json.dumps(o,indent=2)+'\n')
def obj(props,req=None): return {'type':'object','additionalProperties':False,'properties':props,'required':list(props) if req is None else req}
def schema(n,o): dump(n,{'$schema':'https://json-schema.org/draft/2020-12/schema',**o})
def ref(n): return {'$ref':n}
def en(xs): return {'enum':sorted(xs)}
string={'type':'string'}; token={'type':'string','pattern':s.TOKEN.pattern}; dec={'type':'string','pattern':s.DEC.pattern}; integer={'type':'integer','minimum':0}; nullable=lambda x:{'anyOf':[x,{'type':'null'}]}
slug={'type':'string','pattern':s.SLUG.pattern}; seatid={'type':'string','pattern':'^[a-z][a-z0-9-]{0,62}\\.[a-z][a-z0-9-]{0,62}$'}
rosterrow=obj({'seat':seatid,'team':slug,'runtime':en(s.RUNTIME)})
config=obj({'version':{'const':'1.1.0'},'project_id':slug,'title':{'type':'string','minLength':1,'maxLength':160},'roster':{'type':'array','minItems':1,'maxItems':128,'items':rosterrow},'namespace':{**token,'maxLength':128},'ttl_seconds':{'type':'integer','minimum':10,'maximum':600},'bindings':{'type':'object','propertyNames':token,'additionalProperties':seatid,'maxProperties':128}});schema('module-config.schema.json',config)
manifest=obj({'name':{'const':'sentinel-openrig'},'version':{'const':'0.4.0'},'contract_version':{'const':'1.1.0'},'kind':{'const':'openrig-observability-companion'},'runtime':{'const':'python3.11+'},'source':obj({'project':{'const':'smota/openrig-telemetry'},'transport':{'const':'otlp-http-json'},'signals':{'const':['logs','metrics']},'scope_version':{'const':'1'}}),'entrypoint':{'const':'tools/sentinel.py'},'api':{'const':'contracts/openapi.json'},'skill':{'const':'plugin/skills/sentinel-monitor'},'authority':{'const':'read-only'},'local_only':{'const':True}});schema('module-manifest.schema.json',manifest)
base={'kind':en({'metric','log'}),'namespace':token,'instance':token,'observed_ns':dec,'name':string,'value':nullable(dec),'data':obj({'node_id':token,'runtime':en(s.RUNTIME),'label':string,'departure_state':en(s.QUEUE),'closure_reason':en(s.CLOSURE),'start_ns':dec,'boot_epoch':token,'transition_id':dec,'coverage':en({'retained_window','partial','unavailable'}),'prior_generation':token,'new_generation':token,'continuity':{'const':'intermediate_changes_unknown'},'occurred_ns':dec,'gap_id':dec,'gap_from':dec,'gap_through':dec,'identity_provenance':en({'transport:v1','relay:v1','claimed:v1','origin-unknown:v1','principal:v1'})},[])}
rec=obj(base);rec['allOf']=[{'if':{'properties':{'kind':{'const':'metric'}}},'then':{'properties':{'name':en(s.GAUGES|s.COUNTERS|{s.HIST})}}},{'if':{'properties':{'kind':{'const':'log'}}},'then':{'properties':{'name':en({'openrig.queue.transition','openrig.seat.tenure_change.observed','openrig.telemetry.gap','openrig.telemetry.failure'}),'value':{'type':'null'}}}}];schema('observation.schema.json',rec)
seat=obj({'node_id':token,'seat':nullable(seatid),'team':slug,'runtime':nullable(en(s.RUNTIME)),'presence':en(s.PRES),'activity':en(s.ACT),'needs_input':en({'yes','no','unknown'}),'sample_ns':dec});schema('seat-observation.schema.json',seat)
obsrow=obj({'seq':integer,**base});historyrow=obj({'seq':integer,'received_ns':dec,**base});snapshot=obj({'cursor':integer,'high_watermark':integer,'as_of_ns':dec,'mode':en({'observed','replay'}),'history_completeness':{'const':'unknown'},'ttl_seconds':integer,'seats':{'type':'array','items':seat},'recent':{'type':'array','items':obsrow},'communication_available':{'const':False}});schema('snapshot.schema.json',snapshot)
history=obj({'rows':{'type':'array','items':historyrow},'next_cursor':integer,'has_more':{'type':'boolean'}});schema('history.schema.json',history)
status=obj({'module':{'const':'sentinel-openrig'},'version':{'const':'0.4.0'},'project_id':slug,'title':string,'namespace':token,'record_count':integer,'cursor':integer,'last_received_ns':nullable(dec),'history_completeness':{'const':'unknown'},'bindings':integer,'scope':{'const':'local_metadata_only'}});schema('status.schema.json',status)
roster={'type':'array','items':obj({'seat':seatid,'team':slug,'runtime':en(s.RUNTIME)})};schema('roster.schema.json',roster)
api={'openapi':'3.1.0','info':{'title':'Sentinel local observation API','version':'0.4.0','description':'Trusted local user only. No agent control methods. OTLP/HTTP JSON subset for the existing exporter.'},'servers':[{'url':'http://127.0.0.1:8766'}],'paths':{}}
for path,name,params in [('/api/v1/status','status',[]),('/api/v1/roster','roster',[]),('/api/v1/snapshot','snapshot',['at']),('/api/v1/history','history',['after','limit'])]:
 api['paths'][path]={'get':{'operationId':name,'parameters':[{'name':p,'in':'query','schema':{'type':'integer','minimum':1 if p=='limit' else 0,**({'maximum':500} if p=='limit' else {})}} for p in params],'responses':{'200':{'description':'Observed metadata','content':{'application/json':{'schema':ref(name+'.schema.json')}}},'400':{'description':'Invalid cursor/query'},'403':{'description':'Non-local request'},'503':{'description':'Journal unavailable'}}}}
for sig,key in [('logs','resourceLogs'),('metrics','resourceMetrics')]: api['paths']['/v1/'+sig]={'post':{'operationId':'ingest'+sig.title(),'description':'Exporter scope v1; supported fields allowlisted, max 2 MiB. Atomic durable acknowledgement. Not a general OTLP receiver.','requestBody':{'required':True,'content':{'application/json':{'schema':{'type':'object','required':[key],'properties':{key:{'type':'array','items':{'type':'object'}}}}}}},'responses':{'200':{'description':'Accepted or exact normalized duplicates'},'400':{'description':'Invalid or unsupported batch'},'403':{'description':'Local exporter only'},'413':{'description':'Too large'},'415':{'description':'Unsupported encoding'},'503':{'description':'Journal unavailable'}}}}
